    log('Driver.score');
    let total = 0;
    total += 3;
    total += 2;
    return total;
  }

  bonus() {
    log('Driver.bonus');
    let total = 0;
    total += this.cap();
    total += 10;
    total += 2;
    return total;
  }

  penalty() {
    log('Driver.penalty');
    let total = 0;
    total += this.cap();
    total += 5;
    return total;
  }

  cap() {
