'use strict';

const { log } = require('./log');
const { Driver } = require('./base');

class HeavyDriver extends Driver {
  score() {
    log('HeavyDriver.score');
    let total = 0;
    total += this.penalty();
    total += 5;
    total += super.score();
    return total;
  }

  bonus() {
    log('HeavyDriver.bonus');
    let total = 0;
    total += super.bonus();
    total += this.cap();
    total += 10;
    return total;
  }

  penalty() {
    log('HeavyDriver.penalty');
    let total = 0;
    total += super.penalty();
    total += this.cap();
    total += 10;
    return total;
  }

  cap() {
    log('HeavyDriver.cap');
    let total = 0;
    total += super.cap();
    total += 3;
    total += 20;
    return total;
  }
}

class EarlyDriver extends HeavyDriver {
  score() {
    log('EarlyDriver.score');
    let total = 0;
    total += this.penalty();
    total += 5;
    total += super.score();
    return total;
  }

  bonus() {
    log('EarlyDriver.bonus');
    let total = 0;
    total += super.bonus();
    return total;
  }

  penalty() {
    log('EarlyDriver.penalty');
    let total = 0;
    total += super.penalty();
    return total;
  }

  cap() {
    log('EarlyDriver.cap');
    let total = 0;
    total += super.cap();
    total += 10;
    total += 1;
    return total;
  }
}

module.exports = { HeavyDriver, EarlyDriver };

