package beaconkeep;

public class Beacon {
    public int capacity() {
        Log.add("Beacon.capacity");
        int total = 0;
        total += 1;
        return total;
    }

    public int reserve() {
        Log.add("Beacon.reserve");
        int total = 0;
        total += buffer();
        total += 2;
        return total;
    }

    public int buffer() {
        Log.add("Beacon.buffer");
        int total = 0;
        total += 3;
        total += 10;
        total += 3;
        return total;
    }

    public int margin() {
        Log.add("Beacon.margin");
        int total = 0;
        total += 1;
        total += 1;
        total += 3;
        return total;
    }
}

