const { log } = require('./log');
const { Seed } = require('./base');

class LightSeed extends Seed {
  reserve() {
    log('LightSeed.reserve');
    let total = 0;
    total += super.reserve();
    return total;
  }

  buffer() {
    log('LightSeed.buffer');
    let total = 0;
    total += super.buffer();
    return total;
  }

  margin() {
    log('LightSeed.margin');
    let total = 0;
    total += super.margin();
    return total;
  }
}

class DaySeed extends LightSeed {
  capacity() {
    log('DaySeed.capacity');
    let total = 0;
    total += this.reserve();
    total += super.capacity();
    total += 3;
    return total;
  }
}

module.exports = { LightSeed, DaySeed };

